do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-047","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":987146049,"language":"nl"},"before":null,"after":{"work_id":987146049,"language":"nl","bound_author_id":987304014,"text":"Tal Hawkins heeft als enige de vernietiging van zijn dorp overleefd. Na zijn opleiding bij het Conclaaf der Schaduwen krijgt hij de kans dichter bij de verantwoordelijke hertog van Olasko te komen. Hij doet zich voor als edelman en probeert diens vertrouwen te winnen. Daarvoor moet hij echter opdrachten uitvoeren die botsen met wat hem drijft. Zijn verlangen naar wraak wordt zo een beproeving van zijn eigen grenzen. Tussen hofintriges en duistere magie moet Tal kiezen hoeveel hij voor zijn doel wil opofferen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL554727W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p26165733X"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:5043","note":"Retain existing Work5043 King of Foxes / Raymond E. Feist and exact Dutch Koning der Vossen 9789022537336 Hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL554727W","https://data.bibliotheken.nl/id/nbt/p26165733X"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL28291418M","isbn13":"9789022537336","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact boun