jpen wat hun eigen keuzes hebben losgemaakt en of zij de strijd kunnen voorkomen zonder hun onderlinge band opnieuw kwijt te raken.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL17410022W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p436692872"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:3482","note":"Retain existing Work3482 A World Without Princes / Soman Chainani and exact Dutch Een wereld zonder prinsen 9789402711578 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL17410022W","https://data.bibliotheken.nl/id/nbt/p436692872"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL60455541M","isbn13":"9789402711578","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15130867,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-03T09:26:38.922Z","review_batch":"nl