d_cover_url":null,"evidence_url":"https://data.bibliotheken.nl/id/nbt/p440511844","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p440511844"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:3326","note":"Retain existing Work3326 Legends & Lattes / Travis Baldree and exact Dutch Legendes & Lattes 9789020555523 Hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL27591348W","https://data.bibliotheken.nl/id/nbt/p440511844"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL60585853M","isbn13":"9789020555523","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15138951,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"review_status":"approved","reviewed_at":"2026-11-03T09:26:38.922Z","review_batch":"nl-scale-20261102-047"}},{"ref":"d5","relation":"catalog_work_descriptions","key":{"work_id":987146007,"language":"nl"},"before":null,"after":{"work_id":987146007,"language":"nl","bound_author_id":987304010,"text":"Een voorspelling geeft aan dat drie nakomelingen van Vuurster bijzondere macht zullen dragen. Eén van de jonge katten probeert te ontdekken wat die woorden betekenen en denkt dat antwoorden bij de oude geschiedenis van de clans liggen. Zijn zoektocht richt zich op de bergen, waar een andere stam leeft. Ook zijn twee verwanten voelen zich om eigen redenen tot die reis aangetrokken. Wat zij zoeken, blijkt verbonden met geheimen die niet alleen hun eigen toekomst, maar ook hun band met het verleden raken.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL5714309W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p420970088"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:3010","note":"Retain existing Work3010 Outcast / Erin Hunter and exact Dutch Verbannen 9789059245570 paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL5714309W","https://data.bibliotheken.nl/id/nbt/p420970088"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL42925776M","isbn13":"9789059245570","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15096442,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff1743