cal_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL85351W","https://data.bibliotheken.nl/id/nbt/p427681472"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL59621995M","isbn13":"9789401917223","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15105102,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"review_status":"approved","reviewed_at":"2026-11-03T09:26:38.922Z","review_batch":"nl-scale-20261102-047"}},{"ref":"d7","relation":"catalog_work_descriptions","key":{"work_id":987146016,"language":"nl"},"before":null,"after":{"work_id":987146016,"language":"nl","bound_author_id":987346009,"text":"Sloane en Rowan leren elkaar kennen als rivalen die allebei moorden plegen. Hun onverwachte verstandhouding groeit uit tot een terugkerende wedstrijd waarin zij gevaarlijke tegenstanders opzoeken. Gaandeweg verandert de vriendschap ook in een romantische verhouding. Die toenadering maakt de gevolgen van hun eerdere daden niet ongedaan. De roman combineert hun wisselende perspectieven met de vraag of een band standhoudt binnen het gewelddadige spel dat zij zelf hebben georganiseerd. Het is het eerste afzonderlijk leesbare deel van Ruinous Love.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL36775731W","evidence":[{"type":"reviewed_identity_and_bibliography","sourc