nglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15241295,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"review_status":"approved","reviewed_at":"2026-11-03T09:26:38.922Z","review_batch":"nl-scale-20261102-047"}},{"ref":"d29","relation":"catalog_work_descriptions","key":{"work_id":987146029,"language":"nl"},"before":null,"after":{"work_id":987146029,"language":"nl","bound_author_id":987346014,"text":"Een moeder vindt het lichaam van Vivek Oji voor haar deur in een stad in het zuidoosten van Nigeria. De vraag hoe het zover heeft kunnen komen opent een geschiedenis die niet iedereen op dezelfde manier kende. Familieleden proberen Viveks leven te begrijpen, terwijl vrienden en neef Osita andere kanten hebben gezien. Akwaeke Emezi verbindt hun stemmen met herinneringen aan jeugd, toenadering en vervreemding. De roman onderzoekt wat er verborgen blijft wanneer de mensen om iemand heen vooral hun eigen verwachtingen herkennen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL20649783W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p43633819X"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:3435","note":"Retain existing Work3435 The Death of Vivek Oji / Akwaeke Emezi and exact Dutch De dood van Vivek Oji 9789463811606 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-026.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{