brary.org/works/OL37247638W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p440367441"],"checked_at":"2026-11-03T09:26:38.922Z","reference":"work:3439","note":"Retain existing Work3439 The Women / Kristin Hannah and exact Dutch De vergeten vrouwen 9789049202576 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-026.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://openlibrary.org/works/OL37247638W","https://data.bibliotheken.nl/id/nbt/p440367441"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL60075991M","isbn13":"9789049202576","checkedAt":"2026-11-03T09:26:38.922Z","note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","attempts":[{"receipt":"cover-archive-v2-readback.json","coverId":15120651,"status":"bulk_archive_unavailable","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-03T09:26:38.922Z","review_batch":"nl-scale-20261102-047"}},{"ref":"m30","relation":"catalog_edition_metadata","key":{"edition_id":987246033},"before":null,"after":{"edition_id":987246033,"work_id":987146030,"bound_author_id":928300586,"bound_title":"De vergeten vrouwen","bound_language":"dut","bound_isbn13